query SystemMonitoringDashboard {
  healthCheck {
    status
    timestamp
    database
    version
    memory {
      status
      percentage
      message
    }
  }

  systemStats {
    memory {
      used
      free
      total
      percentage
      heap {
        used
        total
        external
        arrayBuffers
      }
    }
    process {
      pid
      cpu
      version
      platform
    }
    database {
      connectionCount
      queryCount
      averageQueryTime
    }
    timestamp
    uptime
  }

  memoryStats {
    used
    free
    total
    percentage
    heap {
      used
      total
      external
      arrayBuffers
    }
  }
}
